const $=s=>document.querySelector(s);
const root=document.documentElement;
const tokens=await fetch('../system/tokens.json').then(r=>{if(!r.ok)throw new Error('设计变量读取失败');return r.json()});
const folders=['项目灵感','海报探索','材质实验'];
const references=['形态参考.svg','色彩参考.svg'];
const images=['assets/form-01.svg','assets/form-02.svg'];
const selected=new Set();let selectionMode=false;let previewIndex=0;let generationTimer;let toastTimer;let taskState='complete';let resultCount=2;
const preference=matchMedia('(prefers-color-scheme: dark)');
function theme(){const chosen=$('#theme').value;const value=chosen==='system'?(preference.matches?'dark':'light'):chosen;root.dataset.theme=value;for(const [key,color] of Object.entries(tokens.themes[value]))root.style.setProperty('--'+key,color);$('#theme-tag').textContent=$('#direction').value.toUpperCase()+' / '+value.toUpperCase()}
function direction(){root.dataset.direction=$('#direction').value;$('#strap').textContent=tokens.directions[$('#direction').value].strap;theme()}
$('#theme').addEventListener('change',theme);preference.addEventListener('change',theme);$('#direction').addEventListener('change',direction);$('#reduce').addEventListener('change',()=>root.dataset.reduce=String($('#reduce').checked));
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3200)}
function openFolder(){ $('#folder-form').reset();$('#folder-error').hidden=true;$('#folder-name').removeAttribute('aria-invalid');$('#folder-dialog').showModal();$('#folder-name').focus() }
function closeFolder(){$('#folder-dialog').close()}
$('#new-folder').addEventListener('click',openFolder);document.querySelectorAll('[data-open-folder]').forEach(b=>b.addEventListener('click',openFolder));$('#cancel-folder').addEventListener('click',closeFolder);$('#close-folder').addEventListener('click',closeFolder);
function renderFolders(){$('#folders').replaceChildren(...folders.map((name,i)=>{const button=document.createElement('button');button.className='folder';const icon=document.createElement('i');icon.ariaHidden='true';const text=document.createElement('span');text.textContent=name;const count=document.createElement('small');count.textContent=['08','12','04'][i]||'00';button.append(icon,text,count);button.addEventListener('click',()=>{document.querySelectorAll('.folder').forEach(b=>b.classList.remove('selected'));button.classList.add('selected');setView('gallery');toast('已打开文件夹：'+name)});return button}))}
$('#folder-form').addEventListener('submit',event=>{event.preventDefault();const name=$('#folder-name').value.trim();if(!name||folders.includes(name)){const text=name?'名称已存在，请使用其他名称。':'请输入文件夹名称。';$('#folder-error').textContent=text;$('#folder-error').hidden=false;$('#folder-name').setAttribute('aria-invalid','true');$('#folder-name').focus();return}folders.push(name);renderFolders();closeFolder();toast('文件夹已创建：'+name)});
function renderReferences(){$('#attachments').replaceChildren(...references.map((name,i)=>{const item=document.createElement('div');item.className='attachment';const chip=document.createElement('i');chip.ariaHidden='true';const label=document.createElement('span');label.textContent=name;const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label','移除参考图 '+name);remove.addEventListener('click',()=>{references.splice(i,1);renderReferences()});item.append(chip,label,remove);return item}));$('#add-reference').disabled=references.length>=6;$('#ratio').disabled=references.length>0}
function addReference(name){if(references.length>=6){toast('最多添加 6 张参考图');return}references.push(name);renderReferences();toast('已添加为参考图，顺序 '+references.length)}
$('#add-reference').addEventListener('click',()=>addReference('参考图 '+(references.length+1)+'.svg'));
function openPreview(i){previewIndex=i%images.length;$('#preview-image').src=images[previewIndex];$('#image-dialog').showModal()}
$('#close-preview').addEventListener('click',()=>$('#image-dialog').close());$('#previous-image').addEventListener('click',()=>{previewIndex=(previewIndex+1)%2;$('#preview-image').src=images[previewIndex]});$('#next-image').addEventListener('click',()=>{previewIndex=(previewIndex+1)%2;$('#preview-image').src=images[previewIndex]});
function renderResults(){const state=taskState;$('#results').replaceChildren(...Array.from({length:resultCount},(_,i)=>{const url=images[i%images.length];const card=document.createElement('article');card.className='result';const view=document.createElement('button');view.className='image-button';view.setAttribute('aria-label','查看图片 '+(i+1));const image=document.createElement('img');image.src=url;image.alt='几何形态研究 '+(i+1);view.append(image);view.addEventListener('click',()=>openPreview(i));const actions=document.createElement('div');actions.className='result-actions';const number=document.createElement('span');number.textContent=String(i+1).padStart(2,'0');const download=document.createElement('button');download.textContent='↓ 下载';download.addEventListener('click',()=>{const a=document.createElement('a');a.href=url;a.download='form-study-'+(i+1)+'.svg';a.click()});const add=document.createElement('button');add.textContent='+ 添加';add.setAttribute('aria-label','添加图片 '+(i+1)+' 为参考图');add.addEventListener('click',()=>addReference('结果 '+(i+1)+'.svg'));actions.append(number,download,add);card.append(view,actions);if(state==='processing'||(state==='partial'&&i===1)){const overlay=document.createElement('div');overlay.className=state==='processing'?'processing-overlay':'error-overlay';if(state==='processing'){overlay.innerHTML='<div class="progress-ticks" aria-hidden="true"><i></i><i></i><i></i><i></i></div><span>正在生成…</span>'}else{overlay.innerHTML='<span class="error-glyph" aria-hidden="true">[ ! ]</span><strong>本张生成失败</strong><p>成功结果已保留。请查看原因后决定是否重新提交。</p>'}card.append(overlay);view.disabled=true;download.disabled=true;add.disabled=true}return card}));$('#status').textContent=state==='processing'?'正在生成 · 请稍候':state==='partial'?'1 / 2 完成 · 1 张失败':resultCount+' / '+resultCount+' 完成';$('#send').disabled=state==='processing';$('#send').textContent=state==='processing'?'生成中…':'发送 ↗'}
$('#scenario').addEventListener('change',()=>{clearTimeout(generationTimer);taskState=$('#scenario').value;if(taskState==='partial')resultCount=2;renderResults()});
function submit(){if(taskState==='processing')return;if(!$('#prompt').value.trim()){toast('请先描述想生成的画面');$('#prompt').focus();return}resultCount=Number($('#quantity').value);taskState='processing';$('#scenario').value='processing';renderResults();generationTimer=setTimeout(()=>{taskState='complete';$('#scenario').value='complete';renderResults();document.querySelectorAll('.result').forEach(r=>r.classList.add('complete-flash'));toast('演示完成：结果已显示')},1600)}
$('#composer').addEventListener('submit',e=>{e.preventDefault();submit()});$('#prompt').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&$('#enter-send').checked){e.preventDefault();submit()}});$('#quantity').addEventListener('change',()=>$('.cost').textContent=$('#quantity').value+' 积分');
function setView(view){const gallery=view==='gallery';$('#creation-view').hidden=gallery;$('#gallery-view').hidden=!gallery;$('#page-title').textContent=gallery?'我的图片':'图像创作';$('#breadcrumb').textContent='工作室 / '+(gallery?'我的图片':'图像创作');$('.hero small').textContent=gallery?'COLLECTION / 02':'CREATION / 01';document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
function renderGallery(){$('#gallery-grid').replaceChildren(...Array.from({length:6},(_,i)=>{const b=document.createElement('button');b.className='gallery-card';b.setAttribute('aria-label','图片 '+(i+1));b.setAttribute('aria-pressed',String(selected.has(i)));const image=document.createElement('img');image.src=images[i%2];image.alt='几何研究 '+(i+1);const label=document.createElement('span');label.textContent='FORM STUDY / '+String(i+1).padStart(2,'0');b.append(image,label);b.addEventListener('click',()=>{if(!selectionMode){openPreview(i);return}selected.has(i)?selected.delete(i):selected.add(i);renderGallery()});return b}));$('#selection-toolbar').hidden=!selectionMode;$('#selected-count').textContent='已选择 '+selected.size+' 张';$('#categorize').disabled=!selected.size}
$('#select-images').addEventListener('click',()=>{selectionMode=!selectionMode;selected.clear();renderGallery()});$('#clear-selection').addEventListener('click',()=>{selectionMode=false;selected.clear();renderGallery()});$('#categorize').addEventListener('click',()=>toast('演示：已将 '+selected.size+' 张图片归入「项目灵感」'));
function density(){const v=$('#density').value;$('#density-value').textContent=v+' / 5';$('#density-sample').style.setProperty('--density',v);$('#density-sample').replaceChildren(...Array.from({length:Number(v)*2},()=>document.createElement('i')))}$('#density').addEventListener('input',density);
$('#validate-name').addEventListener('click',()=>{const bad=folders.includes($('#sample-name').value.trim());$('#sample-error').hidden=!bad;$('#sample-name').setAttribute('aria-invalid',String(bad));if(!bad)toast('名称可以使用')});$('#preview-feedback').addEventListener('click',()=>toast('2 张图片已完成，结果已保留。'));$('#account').addEventListener('click',()=>toast('试点账户 · 示例余额 128 积分'));
const params=new URLSearchParams(location.search);if(['field','signal','studio'].includes(params.get('direction')))$('#direction').value=params.get('direction');if(['light','dark','system'].includes(params.get('theme')))$('#theme').value=params.get('theme');direction();renderFolders();renderReferences();renderResults();renderGallery();density();document.body.dataset.ready='true';
